container_contract.original_compose:
{
  "name": "ocis",
  "services": {
    "ocis": {
      "image": "owncloud/ocis:latest",
      "restart": "unless-stopped",
      "ports": [
        "9200:9200/tcp"
      ],
      "volumes": [
        "ocis-data:/var/lib/ocis",
        "ocis-config:/etc/ocis"
      ],
      "environment": {
        "OCIS_INSECURE": "true",
        "OCIS_URL": "https://@CONTAINER_ADDRESS@:9200",
        "IDM_ADMIN_PASSWORD": "${GENERATED_IDM_ADMIN_PASSWORD}"
      },
      "entrypoint": [
        "/bin/sh",
        "-c"
      ],
      "command": [
        "if [ ! -f /etc/ocis/ocis.yaml ]; then ocis init --insecure true; fi; exec ocis server"
      ]
    }
  },
  "volumes": {
    "ocis-data": {},
    "ocis-config": {}
  }
}
